// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface IERC20Rescue {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IPancakeFactoryV2 {
    function getPair(address tokenA, address tokenB)
        external
        view
        returns (address pair);

    function createPair(address tokenA, address tokenB)
        external
        returns (address pair);
}

interface IPancakeRouterV2 {
    function factory() external view returns (address);
}

/**
 * @title CAIToken (Cyera)
 * @notice Fixed-supply CAI token with restricted PancakeSwap buying.
 *
 * TOKEN RULES AFTER FINAL CONFIGURATION
 * -------------------------------------
 * User            -> User              Allowed
 * User            -> Pancake Pair      Allowed (sell / liquidity add)
 * Pancake Pair    -> User              Blocked (buy)
 * Pancake Pair    -> Mining Contract   Allowed (30% investment auto-buy)
 * Mining Contract -> Pancake Pair      Allowed (ROI auto-sell payout)
 * Mining Contract -> User              Allowed
 * User            -> Mining Contract   Allowed
 * Burn                                 Allowed
 *
 * CONFIGURATION
 * -------------
 * 1. The complete fixed supply (300,000 CAI) is minted to the deployer.
 * 2. The PancakeSwap V2 pair is fetched or created in the constructor.
 * 3. The Mining Contract is configured exactly once.
 * 4. Ownership is automatically renounced after configuration.
 */
contract CAIToken is ERC20, ERC20Burnable, Ownable {
    uint8 private constant TOKEN_DECIMALS = 18;

    uint256 public constant MAX_SUPPLY = 777_777 * 10 ** TOKEN_DECIMALS;

    address public immutable usdt;
    IPancakeRouterV2 public immutable pancakeRouter;
    address public immutable pancakePair;

    address public miningContract;
    bool public configurationLocked;

    error ZeroAddress();
    error InvalidContract(address account);
    error InvalidFactory(address factory);
    error InvalidPair(address pair);
    error InvalidMiningContract(address mining);
    error ConfigurationAlreadyLocked();
    error TransferNotAllowed(address from, address to);
    error PancakeBuyBlocked(address recipient);
    error MiningContractNotConfigured();
    error NoUSDTToRecover();
    error USDTTransferFailed();

    event MiningContractConfigured(
        address indexed miningContract,
        address indexed configuredBy
    );

    event FinalConfigurationLocked(
        address indexed miningContract,
        address indexed pancakePair
    );

    event USDTRecoveredToMining(
        address indexed caller,
        address indexed miningContract,
        uint256 amount
    );

    /**
     * @param usdtAddress USDT token address on BSC.
     * @param routerAddress PancakeSwap V2 Router address on BSC.
     */
    constructor(
        address usdtAddress,
        address routerAddress
    )
        ERC20("Cyera", "CAI")
        Ownable(msg.sender)
    {
        if (
            usdtAddress == address(0) ||
            routerAddress == address(0)
        ) {
            revert ZeroAddress();
        }

        if (usdtAddress.code.length == 0) {
            revert InvalidContract(usdtAddress);
        }

        if (routerAddress.code.length == 0) {
            revert InvalidContract(routerAddress);
        }

        usdt = usdtAddress;
        pancakeRouter = IPancakeRouterV2(routerAddress);

        address factoryAddress = IPancakeRouterV2(routerAddress).factory();

        if (
            factoryAddress == address(0) ||
            factoryAddress.code.length == 0
        ) {
            revert InvalidFactory(factoryAddress);
        }

        IPancakeFactoryV2 factory = IPancakeFactoryV2(factoryAddress);

        address pair = factory.getPair(address(this), usdtAddress);

        if (pair == address(0)) {
            pair = factory.createPair(
                address(this),
                usdtAddress
            );
        }

        if (
            pair == address(0) ||
            pair.code.length == 0
        ) {
            revert InvalidPair(pair);
        }

        pancakePair = pair;

        // The complete supply is minted once to the deployer.
        // No external or public mint function exists.
        _mint(msg.sender, MAX_SUPPLY);
    }

    /**
     * @notice Returns 18 token decimals.
     */
    function decimals()
        public
        pure
        override
        returns (uint8)
    {
        return TOKEN_DECIMALS;
    }

    /**
     * @notice Permanently configures the Mining Contract.
     * @dev This function can execute only once. Ownership is
     *      automatically renounced after successful configuration.
     *
     * The Mining Contract must already be deployed.
     */
    function setMiningContractAndRenounceOwnership(
        address miningAddress
    )
        external
        onlyOwner
    {
        if (configurationLocked) {
            revert ConfigurationAlreadyLocked();
        }

        if (miningAddress == address(0)) {
            revert ZeroAddress();
        }

        if (
            miningAddress.code.length == 0 ||
            miningAddress == address(this) ||
            miningAddress == usdt ||
            miningAddress == address(pancakeRouter) ||
            miningAddress == pancakePair
        ) {
            revert InvalidMiningContract(miningAddress);
        }

        miningContract = miningAddress;
        configurationLocked = true;

        emit MiningContractConfigured(
            miningAddress,
            msg.sender
        );

        emit FinalConfigurationLocked(
            miningAddress,
            pancakePair
        );

        // No administrator remains after final configuration.
        renounceOwnership();
    }

    /**
     * @dev Controls every mint, burn and token transfer.
     *
     * Before final configuration:
     * - Owner -> any address is allowed.
     * - Any address -> owner is allowed.
     * - Transfers not involving the owner are blocked.
     *
     * After final configuration:
     * - Normal wallet transfers are allowed.
     * - Selling to the official Pancake pair is allowed.
     * - The official pair can send CAI only to the Mining Contract.
     */
    function _update(
        address from,
        address to,
        uint256 amount
    )
        internal
        override
    {
        // Constructor mint.
        if (from == address(0)) {
            super._update(from, to, amount);
            return;
        }

        // Burns through burn() or burnFrom() are allowed.
        if (to == address(0)) {
            super._update(from, to, amount);
            return;
        }

        // Before final locking, the current owner must participate
        // in every normal transfer. This permits initial token
        // distribution and liquidity preparation.
        if (!configurationLocked) {
            address currentOwner = owner();

            if (
                from != currentOwner &&
                to != currentOwner
            ) {
                revert TransferNotAllowed(from, to);
            }

            super._update(from, to, amount);
            return;
        }

        // Block purchases from the official PancakeSwap pair.
        // The pair may transfer CAI only to the Mining Contract.
        if (
            from == pancakePair &&
            to != miningContract
        ) {
            revert PancakeBuyBlocked(to);
        }

        // All other normal transfers are allowed.
        super._update(from, to, amount);
    }

    /**
     * @notice Emergency recovery of USDT to Mining Contract.
     */
    function recoverUSDT() external {
        address mining = miningContract;

        if (!configurationLocked || mining == address(0)) {
            revert MiningContractNotConfigured();
        }

        uint256 amount = IERC20Rescue(usdt).balanceOf(address(this));

        if (amount == 0) {
            revert NoUSDTToRecover();
        }

        bool success = IERC20Rescue(usdt).transfer(mining, amount);

        if (!success) {
            revert USDTTransferFailed();
        }

        emit USDTRecoveredToMining(
            msg.sender,
            mining,
            amount
        );
    }
}

contracts/CyeraMiningEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IPancakeRouterV2 {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external
        view
        returns (uint256[] memory amounts);
}

interface IRevenueSplitter {
    function distribute() external returns (uint256, uint256, uint256);
}

/**
 * @title CyeraMiningEngine (Protocol V2)
 * @notice Central Investment & ROI Liquidity Execution Engine for Cyera AI.
 * 
 * EXECUTION FLOW
 * --------------
 * 1. User Investment (invest):
 *    - 30% USDT -> Automatically swapped on PancakeSwap for CAI (Green Buy on DEX chart 🟢).
 *                  Bought CAI tokens are stored in this engine contract to fund future ROI claims.
 *    - 38% USDT -> Transferred directly to USDTWithdrawalVault (Guarantees working/level payout liquidity).
 *    - 32% USDT -> Transferred to RevenueSplitter (splits: 20% Trading + 10% [5 Partners @ 2%] + 2% Reserve).
 *
 * 2. User ROI Claim (sellPortfolio):
 *    - User claims daily mining/staking ROI via EIP-712 authorized signature.
 *    - Engine swaps CAI for USDT on PancakeSwap (Red Sell on DEX chart 🔴).
 *    - Resulting USDT is delivered directly to the user's wallet.
 */
contract CyeraMiningEngine is Ownable {
    IERC20 public immutable usdt;
    IERC20 public immutable caiToken;
    IPancakeRouterV2 public immutable pancakeRouter;

    address public withdrawalVault;
    address public revenueSplitter;
    address public backendSigner;

    // Split percentages (Total = 100%)
    uint256 public constant BUY_PERCENT     = 30; // 30% PancakeSwap Auto-Buy
    uint256 public constant VAULT_PERCENT   = 38; // 38% USDT Withdrawal Vault
    uint256 public constant SPLIT_PERCENT   = 32; // 32% Revenue Splitter

    // EIP-712 Domain Separator constants
    bytes32 private constant CLAIM_TYPEHASH = keccak256(
        "SellPortfolio(address user,uint256 caiAmount,uint256 minUsdtOut,uint256 nonce,uint256 expiry)"
    );
    bytes32 public immutable DOMAIN_SEPARATOR;

    // Prevent nonce reuse for ROI claims
    mapping(address => mapping(uint256 => bool)) public isNonceExecuted;

    // Reentrancy guard
    uint256 private _status;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    // Track total volume
    uint256 public totalInvestedUsdt;
    uint256 public totalCaiPurchased;
    uint256 public totalRoiUsdtPaid;
    uint256 public totalVaultFundedUsdt;
    uint256 public totalSplitterFundedUsdt;

    // Events
    event Invested(
        address indexed user,
        uint256 totalAmountUsdt,
        uint256 indexed packageId,
        uint256 vaultUsdt,
        uint256 splitterUsdt,
        uint256 liquidityUsdt,
        uint256 caiPurchased,
        uint256 timestamp
    );

    event PortfolioSold(
        address indexed user,
        uint256 caiAmountSold,
        uint256 usdtDelivered,
        uint256 indexed nonce,
        uint256 timestamp
    );

    event WithdrawalVaultUpdated(address indexed previousVault, address indexed newVault);
    event RevenueSplitterUpdated(address indexed previousSplitter, address indexed newSplitter);
    event BackendSignerUpdated(address indexed previousSigner, address indexed newSigner);

    error ZeroAddress();
    error InvalidAmount();
    error InvalidSignature();
    error SignatureExpired();
    error NonceAlreadyUsed();
    error TransferFailed();
    error ReentrancyGuardReentrantCall();

    modifier nonReentrant() {
        if (_status == _ENTERED) revert ReentrancyGuardReentrantCall();
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    constructor(
        address _usdt,
        address _caiToken,
        address _pancakeRouter,
        address _withdrawalVault,
        address _revenueSplitter,
        address _backendSigner,
        address _initialOwner
    ) Ownable(_initialOwner) {
        if (
            _usdt == address(0) ||
            _caiToken == address(0) ||
            _pancakeRouter == address(0) ||
            _withdrawalVault == address(0) ||
            _revenueSplitter == address(0) ||
            _backendSigner == address(0) ||
            _initialOwner == address(0)
        ) {
            revert ZeroAddress();
        }

        usdt = IERC20(_usdt);
        caiToken = IERC20(_caiToken);
        pancakeRouter = IPancakeRouterV2(_pancakeRouter);
        withdrawalVault = _withdrawalVault;
        revenueSplitter = _revenueSplitter;
        backendSigner = _backendSigner;
        _status = _NOT_ENTERED;

        // Compute EIP-712 Domain Separator
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("CyeraMiningEngine")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );

        // Pre-approve PancakeSwap router for USDT and CAI transfers
        IERC20(_usdt).approve(_pancakeRouter, type(uint256).max);
        IERC20(_caiToken).approve(_pancakeRouter, type(uint256).max);
    }

    /**
     * @notice Process user package investment:
     *         30% Auto-Buy CAI on PancakeSwap (Held in Engine)
     *         38% USDT to Withdrawal Vault
     *         32% USDT to Revenue Splitter (Trading + Partners + Reserve)
     * @param amountUsdt Total investment amount in USDT (18 decimals).
     * @param packageId Internal package / staking tier identifier.
     */
    function invest(uint256 amountUsdt, uint256 packageId) external nonReentrant {
        if (amountUsdt == 0) revert InvalidAmount();

        // 1. Pull USDT from user to this contract
        bool success = usdt.transferFrom(msg.sender, address(this), amountUsdt);
        if (!success) revert TransferFailed();

        // 2. Exact 30% / 38% / 32% zero-loss calculations
        uint256 buyAmount = (amountUsdt * BUY_PERCENT) / 100;
        uint256 vaultAmount = (amountUsdt * VAULT_PERCENT) / 100;
        uint256 splitterAmount = amountUsdt - buyAmount - vaultAmount; // Exact 32% remainder

        // 3. Fund USDT Withdrawal Vault (38%)
        success = usdt.transfer(withdrawalVault, vaultAmount);
        if (!success) revert TransferFailed();
        totalVaultFundedUsdt += vaultAmount;

        // 4. Fund Revenue Splitter (32%) and trigger instant distribution
        success = usdt.transfer(revenueSplitter, splitterAmount);
        if (!success) revert TransferFailed();
        totalSplitterFundedUsdt += splitterAmount;

        // Attempt instant on-chain distribution in the same transaction
        try IRevenueSplitter(revenueSplitter).distribute() {} catch {}

        // 5. Auto-Buy CAI on PancakeSwap with remaining 30% USDT (Green Buy on DEX chart)
        address[] memory path = new address[](2);
        path[0] = address(usdt);
        path[1] = address(caiToken);

        uint256 caiBefore = caiToken.balanceOf(address(this));

        pancakeRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            buyAmount,
            0, // Accept market execution price
            path,
            address(this), // Engine holds purchased CAI to back future ROI claims
            block.timestamp + 300
        );

        uint256 caiPurchased = caiToken.balanceOf(address(this)) - caiBefore;

        totalInvestedUsdt += amountUsdt;
        totalCaiPurchased += caiPurchased;

        emit Invested(
            msg.sender,
            amountUsdt,
            packageId,
            vaultAmount,
            splitterAmount,
            buyAmount,
            caiPurchased,
            block.timestamp
        );
    }

    /**
     * @notice Claim ROI / Working Income by selling CAI on PancakeSwap for USDT (Delivered to User).
     * @param caiAmount Amount of CAI to swap and sell on PancakeSwap.
     * @param minUsdtOut Minimum acceptable USDT to prevent front-running (pass 0 for market output).
     * @param nonce Unique transaction nonce generated by backend.
     * @param expiry Expiration timestamp for the cryptographic signature.
     * @param signature Cryptographic signature from authorized backendSigner.
     */
    function sellPortfolio(
        uint256 caiAmount,
        uint256 minUsdtOut,
        uint256 nonce,
        uint256 expiry,
        bytes calldata signature
    ) external nonReentrant {
        if (caiAmount == 0) revert InvalidAmount();
        if (block.timestamp > expiry) revert SignatureExpired();
        if (isNonceExecuted[msg.sender][nonce]) revert NonceAlreadyUsed();

        // 1. Verify EIP-712 Cryptographic Signature via ecrecover
        bytes32 structHash = keccak256(
            abi.encode(
                CLAIM_TYPEHASH,
                msg.sender,
                caiAmount,
                minUsdtOut,
                nonce,
                expiry
            )
        );

        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash)
        );

        address recoveredSigner = _recoverSigner(digest, signature);
        if (recoveredSigner == address(0) || recoveredSigner != backendSigner) {
            revert InvalidSignature();
        }

        // 2. Mark nonce as consumed
        isNonceExecuted[msg.sender][nonce] = true;

        // 3. Swap CAI for USDT on PancakeSwap (Red Sell on DEX chart) & deliver USDT to user
        address[] memory path = new address[](2);
        path[0] = address(caiToken);
        path[1] = address(usdt);

        uint256 userUsdtBefore = usdt.balanceOf(msg.sender);

        pancakeRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            caiAmount,
            minUsdtOut,
            path,
            msg.sender, // Deliver USDT directly to user
            block.timestamp + 300
        );

        uint256 usdtDelivered = usdt.balanceOf(msg.sender) - userUsdtBefore;
        totalRoiUsdtPaid += usdtDelivered;

        emit PortfolioSold(
            msg.sender,
            caiAmount,
            usdtDelivered,
            nonce,
            block.timestamp
        );
    }

    /**
     * @dev Internal helper to recover signer from signature using standard ecrecover.
     */
    function _recoverSigner(bytes32 hash, bytes memory sig) internal pure returns (address) {
        if (sig.length != 65) return address(0);

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        if (v != 27 && v != 28) return address(0);

        return ecrecover(hash, v, r, s);
    }

    /**
     * @notice Admin update for USDT Withdrawal Vault.
     */
    function setWithdrawalVault(address _newVault) external onlyOwner {
        if (_newVault == address(0)) revert ZeroAddress();
        address old = withdrawalVault;
        withdrawalVault = _newVault;
        emit WithdrawalVaultUpdated(old, _newVault);
    }

    /**
     * @notice Admin update for Revenue Splitter.
     */
    function setRevenueSplitter(address _newSplitter) external onlyOwner {
        if (_newSplitter == address(0)) revert ZeroAddress();
        address old = revenueSplitter;
        revenueSplitter = _newSplitter;
        emit RevenueSplitterUpdated(old, _newSplitter);
    }

    /**
     * @notice Admin update for Backend Signer.
     */
    function setBackendSigner(address _newSigner) external onlyOwner {
        if (_newSigner == address(0)) revert ZeroAddress();
        address old = backendSigner;
        backendSigner = _newSigner;
        emit BackendSignerUpdated(old, _newSigner);
    }

    /**
     * @notice Emergency recovery for non-protocol tokens accidentally sent to contract.
     */
    function rescueTokens(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        IERC20(token).transfer(to, amount);
    }
}

contracts/RevenueSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

/**
 * @title RevenueSplitter
 * @notice Receives 32% of total investment USDT from CyeraMiningEngine and splits into:
 *         - 20% of total investment (20/32 of incoming USDT) -> Trading Operations Wallet
 *         - 2% of total investment (2/32 of incoming USDT)  -> Partner 1
 *         - 2% of total investment (2/32 of incoming USDT)  -> Partner 2
 *         - 2% of total investment (2/32 of incoming USDT)  -> Partner 3
 *         - 2% of total investment (2/32 of incoming USDT)  -> Partner 4
 *         - 2% of total investment (2/32 of incoming USDT)  -> Partner 5
 *         - 2% of total investment (2/32 of incoming USDT)  -> Operations / Reserve Wallet
 *
 * All wallet addresses are updatable exclusively by the contract Owner.
 */
contract RevenueSplitter is Ownable {
    IERC20 public immutable usdt;

    address public tradingWallet;
    address[5] public partnerWallets;
    address public reserveWallet;

    // Weight allocation (Total = 32 parts corresponding to 32% of package)
    uint256 public constant TRADING_WEIGHT = 20; // 20%
    uint256 public constant PARTNER_WEIGHT = 2;  // 2% each (x 5 = 10%)
    uint256 public constant RESERVE_WEIGHT = 2;  // 2%
    uint256 public constant TOTAL_WEIGHT   = 32; // 32%

    // Volume metrics
    uint256 public totalDistributedUsdt;
    uint256 public totalTradingPaid;
    uint256 public totalPartnersPaid;
    uint256 public totalReservePaid;

    event RevenueDistributed(
        uint256 totalAmount,
        uint256 tradingAmount,
        uint256 partnerAmountEach,
        uint256 reserveAmount,
        uint256 timestamp
    );

    event TradingWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event PartnerWalletUpdated(uint8 indexed index, address indexed oldWallet, address indexed newWallet);
    event ReserveWalletUpdated(address indexed oldWallet, address indexed newWallet);

    error ZeroAddress();
    error InvalidPartnerIndex();
    error NoBalanceToDistribute();
    error TransferFailed();

    constructor(
        address _usdt,
        address _tradingWallet,
        address[5] memory _partnerWallets,
        address _reserveWallet,
        address _initialOwner
    ) Ownable(_initialOwner) {
        if (
            _usdt == address(0) ||
            _tradingWallet == address(0) ||
            _reserveWallet == address(0) ||
            _initialOwner == address(0)
        ) {
            revert ZeroAddress();
        }

        for (uint8 i = 0; i < 5; i++) {
            if (_partnerWallets[i] == address(0)) {
                revert ZeroAddress();
            }
        }

        usdt = IERC20(_usdt);
        tradingWallet = _tradingWallet;
        partnerWallets = _partnerWallets;
        reserveWallet = _reserveWallet;
    }

    /**
     * @notice Distributes all USDT currently held in this contract according to the 20/2/2/2/2/2/2 formula.
     * @dev Can be called automatically by MiningEngine or permissionlessly by anyone.
     */
    function distribute() public returns (
        uint256 tradingAmount,
        uint256 partnerAmountEach,
        uint256 reserveAmount
    ) {
        uint256 balance = usdt.balanceOf(address(this));
        if (balance == 0) revert NoBalanceToDistribute();

        // 20/32 to Trading Wallet
        tradingAmount = (balance * TRADING_WEIGHT) / TOTAL_WEIGHT;

        // 2/32 to each of the 5 Partner Wallets
        partnerAmountEach = (balance * PARTNER_WEIGHT) / TOTAL_WEIGHT;

        // Remainder to Reserve Wallet (guarantees exact 0-loss distribution)
        uint256 totalAllocated = tradingAmount + (partnerAmountEach * 5);
        reserveAmount = balance - totalAllocated;

        totalDistributedUsdt += balance;
        totalTradingPaid += tradingAmount;
        totalPartnersPaid += (partnerAmountEach * 5);
        totalReservePaid += reserveAmount;

        // Execute transfers
        bool success = usdt.transfer(tradingWallet, tradingAmount);
        if (!success) revert TransferFailed();

        for (uint8 i = 0; i < 5; i++) {
            success = usdt.transfer(partnerWallets[i], partnerAmountEach);
            if (!success) revert TransferFailed();
        }

        if (reserveAmount > 0) {
            success = usdt.transfer(reserveWallet, reserveAmount);
            if (!success) revert TransferFailed();
        }

        emit RevenueDistributed(balance, tradingAmount, partnerAmountEach, reserveAmount, block.timestamp);
    }

    /**
     * @notice Admin update for Trading Operations Wallet.
     */
    function setTradingWallet(address _newTrading) external onlyOwner {
        if (_newTrading == address(0)) revert ZeroAddress();
        address old = tradingWallet;
        tradingWallet = _newTrading;
        emit TradingWalletUpdated(old, _newTrading);
    }

    /**
     * @notice Admin update for a specific Partner Wallet (Index 0 to 4).
     */
    function setPartnerWallet(uint8 index, address _newPartner) external onlyOwner {
        if (index >= 5) revert InvalidPartnerIndex();
        if (_newPartner == address(0)) revert ZeroAddress();
        address old = partnerWallets[index];
        partnerWallets[index] = _newPartner;
        emit PartnerWalletUpdated(index, old, _newPartner);
    }

    /**
     * @notice Admin update for Reserve Wallet.
     */
    function setReserveWallet(address _newReserve) external onlyOwner {
        if (_newReserve == address(0)) revert ZeroAddress();
        address old = reserveWallet;
        reserveWallet = _newReserve;
        emit ReserveWalletUpdated(old, _newReserve);
    }

    /**
     * @notice Returns all 5 partner wallet addresses.
     */
    function getPartnerWallets() external view returns (address[5] memory) {
        return partnerWallets;
    }

    /**
     * @notice Emergency recovery for non-USDT tokens sent accidentally.
     */
    function rescueTokens(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        IERC20(token).transfer(to, amount);
    }
}

contracts/test/MockPancakeRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

interface IERC20Transfer {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

contract MockPancakePair is ERC20 {
    address public token0;
    address public token1;

    constructor(address _token0, address _token1) ERC20("Pancake LPs", "Cake-LP") {
        token0 = _token0;
        token1 = _token1;
    }
}

contract MockPancakeFactory {
    mapping(address => mapping(address => address)) public getPair;

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        MockPancakePair newPair = new MockPancakePair(tokenA, tokenB);
        pair = address(newPair);
        getPair[tokenA][tokenB] = pair;
        getPair[tokenB][tokenA] = pair;
    }
